declare(strict_types=1);require_once __DIR__.'/../config/app.php';require_once __DIR__.'/../config/auth.php';require_auth();if($_SERVER['REQUEST_METHOD']!=='POST')json_error('Method not allowed',405);if(empty($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)json_error('Choose a file to upload.',422);$max=defined('WHATSAPP_MAX_MEDIA_BYTES')?WHATSAPP_MAX_MEDIA_BYTES:16777216;if($_FILES['file']['size']>$max)json_error('File is too large.',413);$tmp=$_FILES['file']['tmp_name'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$allow=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','video/mp4'=>'mp4','application/pdf'=>'pdf','text/plain'=>'txt','application/msword'=>'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx'];if(!isset($allow[$mime]))json_error('Unsupported file type.',415);$dir=__DIR__.'/../storage/media/outbox';if(!is_dir($dir))mkdir($dir,0750,true);$ref=bin2hex(random_bytes(16)).'.'.$allow[$mime];if(!move_uploaded_file($tmp,$dir.'/'.$ref))json_error('Could not store upload.',500);json_response(['success'=>true,'media_ref'=>$ref,'mime'=>$mime,'name'=>basename((string)$_FILES['file']['name'])],201);

